<template>
  <q-select
    outlined
    dense
    class="doc-type-select back-white"
    :disable="isReadOnly"
    v-model="selected_doc_type"
    :options="filteredDocTypeOptions"
    @update:model-value="itemClicked"
    emit-value
    map-options
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps" :disable="scope.opt.hasDocTypes">
        <q-item-section>
          <q-item-label
            v-if="scope.opt.doc_type_key"
            :class="
              'pl-20 ' +
              (sub_doc_type === scope.opt.value ? 'q-item--active' : '')
            "
            >{{ scope.opt.label }}</q-item-label
          >
          <q-item-label v-else>{{ scope.opt.label }}</q-item-label>
        </q-item-section>
      </q-item>
    </template>

    <template v-slot:prepend>
      <q-icon flat dense color="grey-9">
        <Icon icon="mdi:file-document" width="20" height="20" class="black_to_white" />
      </q-icon>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';

import {
  useDropdownStore,
  useDocumentStore,
  useDocClassificationStore,
} from 'src/store/main';
import { filterApiDocTypes } from 'src/utils/docTypeFilter';

export default defineComponent({
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  mixins: [],
  
  data() {
    return {};
  },
  mounted() {
    this.filteredDocTypeOptions = filterApiDocTypes(this.active_doc_types_sub_types_list);
  },
  methods: {
    itemClicked() {
      let filterRecord = this.sub_types_list.filter((v: any) => {
        return v.value == this.selected_doc_type;
      });
      filterRecord = filterRecord[0] || null;
      if (!filterRecord) {
        this.restart_classification_popup = true;
        return;
      }

      if (
        !filterRecord.hasOwnProperty('model_label_id') ||
        !filterRecord.model_label_id
      ) {
        this.restart_classification_popup = true;
        return;
      }
      this.selected_custom_model_label = filterRecord.model_label_id;
      this.label_classification_popup = true;
    },
  },

  setup() {
    const classification_store = useDocClassificationStore();
    const {
      restart_classification_popup,
      label_classification_popup,
      selected_custom_model_label,
    } = storeToRefs(classification_store);

    const dropdown_store = useDropdownStore();
    const { active_doc_types_sub_types_list, sub_types_list } =
      storeToRefs(dropdown_store);

    const doc_store = useDocumentStore();
    const { selected_doc_type, sub_doc_type } = storeToRefs(doc_store);

    const filteredDocTypeOptions = ref([] as any);

    return {
      selected_custom_model_label,
      label_classification_popup,
      restart_classification_popup,
      selected_doc_type,
      active_doc_types_sub_types_list,
      filteredDocTypeOptions,
      sub_doc_type,
      sub_types_list,
    };
  },
});
</script>
