<template>
  <q-select
    outlined
    denses
    v-model="selected_page"
    :options="pages_list"
    emit-value
    map-options
    :label="$t('Start Page')"
  >
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDocumentStore, useDocClassificationStore } from 'src/store/main';

export default defineComponent({
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  mixins: [],
  components: {},
  data() {
    return {};
  },
  methods: {},

  setup() {
    const doc_store = useDocumentStore();
    const { pages_list } = storeToRefs(doc_store);

    const classification_store = useDocClassificationStore();
    const { selected_page } = storeToRefs(classification_store);

    return {
      pages_list,
      selected_page,
    };
  },
});
</script>
