<template>
  <q-card style="width: 500px">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title></q-toolbar-title>
      <q-btn
        flat
        round
        dense
        icon="close"
        v-close-popup
        @click="resetClassification"
      />
    </q-toolbar>

    <q-card-section>
      <div class="row">
        <div class="col-12 q-mb-sm">
          <docTypeDropdown :isReadOnly="isReadOnly" />
        </div>

        <div class="col-12 q-mb-sm">
          <LanguageDropdown class="full-width" :isReadOnly="isReadOnly" />
        </div>
      </div>
    </q-card-section>

    <q-card-actions align="right" v-if="!isReadOnly">
      <f-btn
        appearance="cancel"
        :label="$t('cancel')"
        v-close-popup
        @click="resetClassification"
      />
      <f-btn
        :label="$t('proceed')"
        v-close-popup
        @click="triggerNewClassification"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import docTypeDropdown from 'src/components/document/classification/doc_type_dropdown.vue';
import LanguageDropdown from 'src/components/document/classification/language_dropdown.vue';
import { useDocClassificationStore, useDocumentStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  el: '#app',
  mixins: [],
  components: {
    docTypeDropdown,
    LanguageDropdown,
  },
  props: {
    isReadOnly: {
      type: Boolean,
      default: true,
    },
  },
  mounted: function () {
    // mountded
  },
  methods: {
    resetClassification() {
      this.resetStore();
      this.setDocTypeAndLanguageOrigin();
    },
    triggerNewClassification() {
      this.trigger_classification = true;
    },
  },
  setup() {
    const classification_store = useDocClassificationStore();
    const { resetStore } = classification_store;
    const { trigger_classification, reset_classification } =
      storeToRefs(classification_store);

    const doc_store = useDocumentStore();
    const { setDocTypeAndLanguageOrigin } = doc_store;

    return {
      resetStore,
      trigger_classification,
      reset_classification,
      setDocTypeAndLanguageOrigin,
    };
  },
});
</script>
