<template>
  <q-icon
    class="q-mr-sm cursor-pointer classification-icon"
    @click="displayPopup"
    v-if="display_btn"
  >
    <Icon icon="mdi:tag-multiple" width="24" height="24" />
    <q-tooltip>Re-Classifiy Document</q-tooltip>
  </q-icon>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';

import { useDocumentStore, useDocClassificationStore } from 'src/store/main';
import { isObjectEmtpy } from 'src/utils/general';

export default defineComponent({
  props: {},
    watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  
  data() {
    return {};
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      if (
        this.record.hasOwnProperty('classification') &&
        !isObjectEmtpy(this.record.classification)
      ) {
        this.display_btn = true;
      }
    },

    displayPopup() {
      this.label_classification_popup = true;
    },
  },

  setup() {
    const doc_store = useDocumentStore();
    const { record, doc_loaded } = storeToRefs(doc_store);

    const classification_store = useDocClassificationStore();
    const { label_classification_popup } = storeToRefs(classification_store);

    return {
      doc_loaded,
      record,
      label_classification_popup,
      display_btn: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.classification-icon {
  font-size: 30px;
}
</style>
